L27_1.m_Pos = "L"
L27_1.m_Talk_KOREA = "당신의 모습도, 목소리도 결코 이 아이에게 닿지 않는답니다."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "あなたの姿も、声も、決してこの子に届くことはありません。"
L27_1.m_Talk_ENG = "Your face, your voice. None of it will ever reach her."
