L27_1.m_Talk_DEU = "Your face, your voice. None of it will ever reach her."
L27_1.m_Talk_FRA = "Your face, your voice. None of it will ever reach her."
L28_1 = {}
L28_1.m_CutScenKey_Talk = "EP13_ACT4_STAGE2_START@16#Talk"
L28_1.m_CutScenProcessKey = 28
