L28_1.m_CharStrID = "SWAN_SIX_NULL_NULL"
L28_1.m_Pos = "L"
L28_1.m_Talk_KOREA = "이 아이는 그저 제가 머릿속에 심어둔 각본대로 이 세계를 재현하고 있을 뿐이니까요."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "この子はただ、私が頭の中に植え付けておいた脚本どおりにこの世界を再現しているだけですから。"
L28_1.m_Talk_ENG = "She's simply playing out the script I planted in her mind. Recreating this world exactly as I wrote it."
L28_1.m_Talk_TWN = "這個孩子只是在按照我在她腦海中植入的劇本，重現這個世界而已。"
L28_1.m_Talk_SCN = "这个孩子只是在按照我在她脑海中植入的剧本，重现这个世界而已。"
L28_1.m_Talk_DEU = "She's simply playing out the script I planted in her mind. Recreating this world exactly as I wrote it."
L28_1.m_Talk_FRA = "She's simply playing out the script I planted in her mind. Recreating this world exactly as I wrote it."
