L16_1.m_Pos = "L"
L17_1 = "이 세계와 이곳에 속한 이들은 세피라와 제 기억을 통해, 재창조된 허구에 불과합니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "この世界とここに属する者たちは、セフィラと私の記憶から再創造された作り物に過ぎません。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "This world and everyone in it were recreated from Sephira and my memories. They're just fiction."
L16_1.m_Talk_ENG = L17_1
L17_1 = "這個世界和屬於這裡的人們，只是通過世界樹和我的記憶重新創造的虛構產物。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "这个世界和属于这里的人们，只是通过赛菲拉和我的记忆重新创造的虚构产物。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "This world and everyone in it were recreated from Sephira and my memories. They're just fiction."
L16_1.m_Talk_DEU = L17_1
L17_1 = "This world and everyone in it were recreated from Sephira and my memories. They're just fiction."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "EP13_ACT4_STAGE2_START@39#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 614
L17_1.m_CutScenStrID = "EP13_ACT4_STAGE2_START"
