L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "SWAN_SIX_NULL_NULL"
L17_1.m_Pos = "L"
L18_1 = "그마저도 제가 경험하지 못했던 부분은 재구성할 수 없는 불완전한 세계라고 할 수 있죠."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "しかも私が経験できなかった部分は再構成できない、不完全な世界です。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "And even then, the parts I never experienced couldn't be reconstructed. It's an incomplete world."
L17_1.m_Talk_ENG = L18_1
L18_1 = "最起碼那些我未曾經歷的部分是無法重構的。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "最起码那些我未曾经历的部分是无法重构的。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "And even then, the parts I never experienced couldn't be reconstructed. It's an incomplete world."
L17_1.m_Talk_DEU = L18_1
L18_1 = "And even then, the parts I never experienced couldn't be reconstructed. It's an incomplete world."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
