L18_1.m_Pos = "L"
L19_1 = "그럼에도 당신은 만들어진 허구를 동정할 셈인가요?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "それでもあなたは、作られた虚構に同情しますか？"
L18_1.m_Talk_JPN = L19_1
L19_1 = "And yet, you still pity this fabricated fiction?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "即便如此，你也打算同情被創造出來的虛構之物嗎？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "即便如此，你也打算同情被创造出来的虚构之物吗？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "And yet, you still pity this fabricated fiction?"
L18_1.m_Talk_DEU = L19_1
