L22_1.m_CharScale = L23_1
L22_1.m_CharScaleTime = 0.01
L23_1 = "무엇이든 탄생하려는 자는 하나의 세계를 부숴야 한다는 말이 있죠."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "生まれようとする者は、まず1つの世界を壊す必要があると言いますね。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "There's a saying that for something new to be born, an old world must first be destroyed."
L22_1.m_Talk_ENG = L23_1
L23_1 = "據說，任何想要誕生的事物都必須打破一個世界。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "据说，任何想要诞生的事物都必须打破一个世界。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "There's a saying that for something new to be born, an old world must first be destroyed."
L22_1.m_Talk_DEU = L23_1
L23_1 = "There's a saying that for something new to be born, an old world must first be destroyed."
