L23_1.m_CharScale = L24_1
L23_1.m_CharScaleTime = 0.01
L24_1 = "저는 이 손으로 여러 세계를 무너트려 왔습니다. 그러니 고향 세계 또한 예외는 아니에요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "私はこの手で、数多くの世界を滅ぼしてきました。故郷の世界といえど、例外ではありません。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "I've already destroyed countless worlds with these hands. My home world is no exception."
L23_1.m_Talk_ENG = L24_1
L24_1 = "我用這雙手摧毀了多個世界，故鄉的世界也不例外。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "我用这双手摧毁了多个世界，故乡的世界也不例外。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "I've already destroyed countless worlds with these hands. My home world is no exception."
L23_1.m_Talk_DEU = L24_1
L24_1 = "I've already destroyed countless worlds with these hands. My home world is no exception."
L23_1.m_Talk_FRA = L24_1
