L24_1.m_CharScale = L25_1
L24_1.m_CharScaleTime = 0.01
L25_1 = "제가 원하는 것을 이루기 위해서라면, 몇 번이든 이곳 런던을 부술 수 있죠."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "私の望みを叶えるためなら、何度だってこのロンドンを壊しましょう。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "If it means getting what I want, I'll destroy this London as many times as it takes."
L24_1.m_Talk_ENG = L25_1
L25_1 = "為了實現我的願望，我可以無數次摧毀這座倫敦。"
