L35_1.m_fTalkTime = 0.03
L36_1 = "あなただけは、いつまでも美しく優雅な白鳥でいて欲しいから。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I want you to always remain a beautiful, graceful swan, no matter where you are."
