L35_1 = "세계를 되돌리겠다고요? 그렇게 과거에 집착한다고 해서 뭐가 달라지죠?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "世界を元に戻す？　そうやって過去に執着したところで何が変わるんですか？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Rewind the world? What good is clinging to the past going to do?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "要把世界恢復原狀嗎？就算那麼執著於過去，又能改變什麼？？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "要把世界恢复原状吗？就算那么执着于过去，又能改变什么呢？"
