L15_1 = "어쨌든 네가 코어를 노린다고 해도, 나 혼자 허신의 공격을 전부 막아내는 건 무리야."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "とにかく、あんたがコアを狙うにしても、あたし一人で虚神の攻撃を全部防ぐのは無理。"
