L20_1 = "아무래도 당신들과는 참 질긴 인연으로 맺어진 모양이네요."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "どうやらあなたたちとは、腐れ縁で結ばれているようです。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Seems we really are bound by some persistent fate, aren't we?"
