L21_1 = "설마, 마지막 순간에 절 막아서는 게… 또다시 병든 병아리들과 저 패배자일 줄이야."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "まさか、最後の最後に私の前に立ちはだかるのが……またもや死にかけのヒヨコたちに、あの敗北者とは。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "To think that at the very end, the ones trying to stop me again... would be those sickly chicks and that loser."
L20_1.m_Talk_ENG = L21_1
L21_1 = "沒想到，在最後一刻擋住我的……竟然又是那些病弱的小雞仔和那個手下敗將。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "没想到，在最后一刻挡住我的……竟然又是那些病弱的小鸡仔和那个手下败将。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "To think that at the very end, the ones trying to stop me again... would be those sickly chicks and that loser."
