L25_1 = "스완! 무슨 짓을 꾸미는지는 모르겠지만 그만두는 게 좋을 거예요!"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "スワン！　何を企んでいるのかは知りませんが、諦めた方がいいですよ！"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Swan! I don't know what you're planning, but you'd better stop now!"
