L36_1.m_Pos = "C"
L37_1 = "확실히 그럴지도 모르겠군요. 현실에서 저는 당신들의 행방을 놓치고 말았죠."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "確かにそうかもしれませんね。現実での私は、あなたたちの行方を見失ってしまった。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Maybe so. I did lose track of you in the real world."
L36_1.m_Talk_ENG = L37_1
L37_1 = "確實可能是這樣。在現實中，我失去了你們的蹤跡。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "确实可能是这样。在现实中，我失去了你们的踪迹。"
