L38_1 = "EP13_ACT4_STAGE2_START@210#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 337
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 614
L37_1.m_CutScenStrID = "EP13_ACT4_STAGE2_START"
