L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "SWAN_SIX_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "그런데 설마 저보다 먼저 제 각본을 꿰뚫어 본 사람이 있을 줄이야. 대단하네요, 그 사람은."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "しかし、まさか私よりも先にこの脚本を見抜いていた人がいたとは。すごいですね、その方。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "But I never imagined someone could see through my script before I even finished it. That person must be something else."
L37_1.m_Talk_ENG = L38_1
L38_1 = "不過，沒想到居然有人比我更早看穿了我的劇本。那個人確實很厲害。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "不过，没想到居然有人比我更早看穿了我的剧本。那个人确实很厉害。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "But I never imagined someone could see through my script before I even finished it. That person must be something else."
L37_1.m_Talk_DEU = L38_1
L38_1 = "But I never imagined someone could see through my script before I even finished it. That person must be something else."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
