L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 338
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 614
L38_1.m_CutScenStrID = "EP13_ACT4_STAGE2_START"
