L38_1.m_CharStrID = "SWAN_SIX_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "하지만 이제 와서 달라지는 건 아무것도 없을 겁니다."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ですが、今更変わることは何もありません。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Still, it's far too late to change anything now."
L38_1.m_Talk_ENG = L39_1
L39_1 = "但如今再怎麼做也不會有任何改變。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "但如今再怎么做也不会有任何改变。"
