L39_1.m_CharStrID = "SWAN_SIX_NULL_NULL"
L39_1.m_Pos = "C"
L40_1 = "결말에 다다른 각본을 막아서기에는, 당신들은 너무나 작고 미약한 존재니까요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "結末に差し掛かった脚本を止めるには、あなたたちはあまりにも小さく微弱な存在ですから。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "You're too insignificant, too powerless to stop a script already nearing its final act."
L39_1.m_Talk_ENG = L40_1
